(async () => {
  const zones = await (await fetch('/api/zones')).json();
  const z = zones.find((x) => x.name === 'delattre-26');
  const i = z && z.instances.find((i) => String(i.url || '').startsWith('social.') || i.label === 'Réseau social');
  if (!i) { console.log('Instance du réseau social introuvable. Instances de la zone :', z ? z.instances.map((i) => i.id + ' | ' + i.label + ' | ' + i.url) : 'zone absente'); return; }
  console.log('Instance trouvée : identifiant « ' + i.id + ' », nom « ' + i.label + ' »');
  const r = await fetch('/api/zones/delattre-26/instances/' + i.id + '/icon/upload', { method: 'POST', headers: { 'Content-Type': 'image/webp' }, body: Uint8Array.from(atob(''), (c) => c.charCodeAt(0)) });
  console.log('Réponse', r.status, await r.json());
})();
